if(typeof require==='function'){var Classy=require('./classy');}var ChatPost=Classy.newClass().name('ChatPost');ChatPost.fields({from:[],to:[],message:"",chatMessageId:0,sendReceipt:""});ChatPost.constructor(function(from,to,message,chatMessageId,sendReceipt){this.from=from;this.to=to;this.message=message;this.chatMessageId=chatMessageId;this.sendReceipt=sendReceipt;});ChatPost.methods({getFrom:function(){return this.from;},getTo:function(){return this.to;},getMessage:function(){return this.message;},getChatMessageId:function(){return this.chatMessageId;},getSendReceipt:function(){return this.sendReceipt;}});if(typeof module==='object'){module.exports=ChatPost;}